# Let's try to build a replacement sequence step by step
# First, let's see if we can find what characters are being transformed

inputs = ['zkg', 'jvwfa', 'kja', 'hfvb', 'hx']
outputs = ['zkybyb', 'jvwfkyv', 'kjkyv', 'hfcu', 'hyby']

# Try to identify character mappings
char_mappings = {}

for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    # Check character by character
    for i in range(min_len):
        if i < len(inp) and i < len(outp) and inp[i] != outp[i]:
            if inp[i] not in char_mappings:
                char_mappings[inp[i]] = outp[i]
            else:
                # If we already have a mapping, check consistency
                if char_mappings[inp[i]] != outp[i]:
                    print(f"Conflict: {inp[i]} maps to both {char_mappings[inp[i]]} and {outp[i]}")

print("Character mappings found:", char_mappings)

# Also look for patterns in the longer outputs
# Check what gets added in each case
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {outp}")
    if len(outp) > len(inp):
        added_chars = outp[len(inp):]
        print(f"  Added chars: {added_chars}")

